=== FILE: rtl/axil_timer.v ===
// axil_timer: AXI4-Lite timer peripheral with interrupt.
// Implements prj-ada3a9b9d9 microarchitecture spec (sections 5 and 6).
// Requirement: req-2b2b91a584.
// Open choice TMR-LOAD-END-EDGE: the old (pre-edge) LOAD is reloaded.
`default_nettype none

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    // ------------------------------------------------------------------
    // State registers (microarchitecture section 3)
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held_q;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;
    reg                  bvalid_q;
    reg [1:0]            bresp_q;
    reg                  rvalid_q;
    reg [1:0]            rresp_q;
    reg [31:0]           rdata_q;
    reg                  en_q;
    reg                  ie_q;
    reg                  mode_q;
    reg [31:0]           load_q;
    reg [31:0]           count_q;
    reg                  expired_q;

    // ------------------------------------------------------------------
    // Readies and outputs (section 5.1): registered state only
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held_q && !bvalid_q;
    assign s_axil_wready  = !w_held_q && !bvalid_q;
    assign s_axil_arready = !rvalid_q;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;
    assign irq            = expired_q && ie_q;

    // ------------------------------------------------------------------
    // Write path (section 5.3)
    // ------------------------------------------------------------------
    wire                  aw_acc;
    wire                  w_acc;
    wire                  wr_fire;
    wire [ADDR_WIDTH-1:0] wa;
    wire [31:0]           wd;
    wire [3:0]            ws;
    wire                  wa_mapped;
    wire                  wr_ok;
    wire                  wr_ctrl;
    wire                  wr_load;
    wire                  wr_clr;

    assign aw_acc    = s_axil_awvalid && s_axil_awready;
    assign w_acc     = s_axil_wvalid && s_axil_wready;
    assign wr_fire   = (aw_acc || aw_held_q) && (w_acc || w_held_q);
    assign wa        = aw_held_q ? aw_addr_q : s_axil_awaddr;
    assign wd        = w_held_q ? w_data_q : s_axil_wdata;
    assign ws        = w_held_q ? w_strb_q : s_axil_wstrb;
    assign wa_mapped = (wa[1:0] == 2'b00) && ((wa >> 4) == {ADDR_WIDTH{1'b0}});
    assign wr_ok     = wa_mapped && (wa[3:2] != 2'd2);
    assign wr_ctrl   = wr_fire && wr_ok && (wa[3:2] == 2'd0) && ws[0];
    assign wr_load   = wr_fire && wr_ok && (wa[3:2] == 2'd1);
    assign wr_clr    = wr_fire && wr_ok && (wa[3:2] == 2'd3) && ws[0] && wd[0];

    // ------------------------------------------------------------------
    // Read path (section 5.4): pre-edge register values
    // ------------------------------------------------------------------
    wire       ar_acc;
    wire       ra_mapped;
    reg [31:0] rmux;

    assign ar_acc    = s_axil_arvalid && s_axil_arready;
    assign ra_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                       ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

    always @* begin
        case (s_axil_araddr[3:2])
            2'd0:    rmux = {29'd0, mode_q, ie_q, en_q};
            2'd1:    rmux = load_q;
            2'd2:    rmux = count_q;
            default: rmux = {31'd0, expired_q};
        endcase
    end

    // ------------------------------------------------------------------
    // Timer core next state (section 6)
    // ------------------------------------------------------------------
    wire        end_ev;
    wire [31:0] end_val;
    wire [31:0] dec_val;
    reg         en_d;
    reg         ie_d;
    reg         mode_d;
    reg         expired_d;
    reg  [31:0] count_d;
    reg  [31:0] load_d;

    assign end_ev  = en_q && (count_q <= 32'd1);
    assign end_val = mode_q ? load_q : 32'd0;
    assign dec_val = count_q - 32'd1;

    always @* begin
        en_d    = en_q;
        ie_d    = ie_q;
        mode_d  = mode_q;
        count_d = count_q;
        if (wr_ctrl) begin
            // Rows 1 and 2: a CTRL write wins for EN and COUNT
            ie_d   = wd[1];
            mode_d = wd[2];
            if (wd[0]) begin
                en_d    = 1'b1;
                count_d = load_q;
            end else begin
                en_d = 1'b0;
                if (end_ev) begin
                    count_d = end_val;
                end else if (en_q) begin
                    count_d = dec_val;
                end else begin
                    count_d = count_q;
                end
            end
        end else if (end_ev) begin
            // Rows 3 and 4: one-shot end / periodic reload
            en_d    = mode_q;
            count_d = end_val;
        end else if (en_q) begin
            // Row 5: decrement
            count_d = dec_val;
        end
    end

    always @* begin
        if (end_ev) begin
            expired_d = 1'b1;
        end else if (wr_clr) begin
            expired_d = 1'b0;
        end else begin
            expired_d = expired_q;
        end
    end

    always @* begin
        load_d = load_q;
        if (wr_load) begin
            if (ws[0]) load_d[7:0]   = wd[7:0];
            if (ws[1]) load_d[15:8]  = wd[15:8];
            if (ws[2]) load_d[23:16] = wd[23:16];
            if (ws[3]) load_d[31:24] = wd[31:24];
        end
    end

    // ------------------------------------------------------------------
    // Registers: synchronous active-low reset on every flop
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held_q  <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= 2'b00;
            rvalid_q  <= 1'b0;
            rresp_q   <= 2'b00;
            rdata_q   <= 32'd0;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
            expired_q <= 1'b0;
        end else begin
            // Write channel
            if (wr_fire) begin
                aw_held_q <= 1'b0;
                w_held_q  <= 1'b0;
                bvalid_q  <= 1'b1;
                bresp_q   <= wr_ok ? 2'b00 : 2'b10;
            end else begin
                if (aw_acc) begin
                    aw_held_q <= 1'b1;
                    aw_addr_q <= s_axil_awaddr;
                end
                if (w_acc) begin
                    w_held_q <= 1'b1;
                    w_data_q <= s_axil_wdata;
                    w_strb_q <= s_axil_wstrb;
                end
                if (bvalid_q && s_axil_bready) begin
                    bvalid_q <= 1'b0;
                end
            end
            // Read channel
            if (ar_acc) begin
                rvalid_q <= 1'b1;
                rdata_q  <= ra_mapped ? rmux : 32'd0;
                rresp_q  <= ra_mapped ? 2'b00 : 2'b10;
            end else if (rvalid_q && s_axil_rready) begin
                rvalid_q <= 1'b0;
            end
            // Registers and timer
            en_q      <= en_d;
            ie_q      <= ie_d;
            mode_q    <= mode_d;
            load_q    <= load_d;
            count_q   <= count_d;
            expired_q <= expired_d;
        end
    end

`ifdef FORMAL
    // Design-intent invariants (microarchitecture section 9). Not proven.
    always @(*) begin
        if (aresetn) begin
            assert (!(aw_held_q && w_held_q));
            assert (!bvalid_q || (!aw_held_q && !w_held_q));
            assert (!bvalid_q || (bresp_q == 2'b00) || (bresp_q == 2'b10));
            assert (!rvalid_q || (rresp_q == 2'b00) || (rresp_q == 2'b10));
            assert (!(rvalid_q && (rresp_q == 2'b10)) || (rdata_q == 32'd0));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: tb/tb_axil_timer.v ===
// Self-checking testbench for axil_timer (prj-ada3a9b9d9, req-2b2b91a584).
// Runs the same suite on ADDR_WIDTH 4 and ADDR_WIDTH 8 instances.
module tb_axil_timer;

    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;
    localparam [1:0] OKAY     = 2'b00;
    localparam [1:0] SLVERR   = 2'b10;

    reg         aclk;
    reg         aresetn;
    reg         sel;      // 0: ADDR_WIDTH 4 instance, 1: ADDR_WIDTH 8 instance
    reg  [7:0]  awaddr;
    reg         awvalid;
    reg  [31:0] wdata;
    reg  [3:0]  wstrb;
    reg         wvalid;
    reg         bready;
    reg  [7:0]  araddr;
    reg         arvalid;
    reg         rready;

    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk(aclk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid & ~sel), .s_axil_awready(awready4),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & ~sel), .s_axil_wready(wready4),
        .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready & ~sel),
        .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid & ~sel), .s_axil_arready(arready4),
        .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready & ~sel),
        .irq(irq4));

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk(aclk), .aresetn(aresetn),
        .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid & sel), .s_axil_awready(awready8),
        .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid & sel), .s_axil_wready(wready8),
        .s_axil_bresp(bresp8), .s_axil_bvalid(bvalid8), .s_axil_bready(bready & sel),
        .s_axil_araddr(araddr), .s_axil_arvalid(arvalid & sel), .s_axil_arready(arready8),
        .s_axil_rdata(rdata8), .s_axil_rresp(rresp8), .s_axil_rvalid(rvalid8), .s_axil_rready(rready & sel),
        .irq(irq8));

    wire        awready_o = sel ? awready8 : awready4;
    wire        wready_o  = sel ? wready8  : wready4;
    wire        bvalid_o  = sel ? bvalid8  : bvalid4;
    wire [1:0]  bresp_o   = sel ? bresp8   : bresp4;
    wire        arready_o = sel ? arready8 : arready4;
    wire        rvalid_o  = sel ? rvalid8  : rvalid4;
    wire [1:0]  rresp_o   = sel ? rresp8   : rresp4;
    wire [31:0] rdata_o   = sel ? rdata8   : rdata4;
    wire        irq_o     = sel ? irq8     : irq4;

    integer passed;
    integer failed;
    integer edge_cnt;
    reg     chk_en;
    reg [8*64-1:0] nonce;

    reg [1:0]  last_bresp;
    reg [1:0]  last_rresp;
    reg [31:0] last_rdata;
    integer    wr_cmpl_edge;
    integer    rd_acc_edge;
    integer    irq_at;

    // ---------------------------------------------------------------
    // Clock and edge counter
    // ---------------------------------------------------------------
    always #5 aclk = ~aclk;
    always @(posedge aclk) edge_cnt <= edge_cnt + 1;

    // ---------------------------------------------------------------
    // Helpers for the reference model
    // ---------------------------------------------------------------
    function [7:0] eff;
        input [7:0] a;
        begin
            eff = sel ? a : {4'h0, a[3:0]};
        end
    endfunction

    function mapped;
        input [7:0] a;
        begin
            mapped = (a[1:0] == 2'b00) && (a[7:4] == 4'h0);
        end
    endfunction

    // ---------------------------------------------------------------
    // Reference model, written from interface spec sections 4, 6, 7, 8, 9
    // ---------------------------------------------------------------
    reg        m_awheld;
    reg [7:0]  m_awaddr;
    reg        m_wheld;
    reg [31:0] m_wdata;
    reg [3:0]  m_wstrb;
    reg        m_bvalid;
    reg [1:0]  m_bresp;
    reg        m_rvalid;
    reg [1:0]  m_rresp;
    reg [31:0] m_rdata;
    reg        m_en;
    reg        m_ie;
    reg        m_mode;
    reg [31:0] m_load;
    reg [31:0] m_count;
    reg        m_expired;

    always @(posedge aclk) begin : model_blk
        reg        t_awa, t_wa, t_ara, t_fire, t_ok, t_end, t_clr, t_ctrl, t_loadw;
        reg [7:0]  t_ea, t_ra;
        reg [31:0] t_ed, t_rv, n_load, n_count;
        reg [3:0]  t_es;
        reg        n_en, n_ie, n_mode, n_exp;
        integer    i;
        if (!aresetn) begin
            m_awheld = 1'b0; m_awaddr = 8'd0; m_wheld = 1'b0; m_wdata = 32'd0; m_wstrb = 4'd0;
            m_bvalid = 1'b0; m_bresp = 2'b00; m_rvalid = 1'b0; m_rresp = 2'b00; m_rdata = 32'd0;
            m_en = 1'b0; m_ie = 1'b0; m_mode = 1'b0; m_load = 32'd0; m_count = 32'd0; m_expired = 1'b0;
        end else begin
            t_awa  = awvalid && !m_awheld && !m_bvalid;
            t_wa   = wvalid && !m_wheld && !m_bvalid;
            t_ara  = arvalid && !m_rvalid;
            t_fire = (t_awa || m_awheld) && (t_wa || m_wheld);
            t_ea   = m_awheld ? m_awaddr : eff(awaddr);
            t_ed   = m_wheld ? m_wdata : wdata;
            t_es   = m_wheld ? m_wstrb : wstrb;
            t_ok   = mapped(t_ea) && (t_ea[3:2] != 2'd2);
            t_ctrl = t_fire && t_ok && (t_ea[3:2] == 2'd0) && t_es[0];
            t_loadw = t_fire && t_ok && (t_ea[3:2] == 2'd1);
            t_clr  = t_fire && t_ok && (t_ea[3:2] == 2'd3) && t_es[0] && t_ed[0];

            // timer progression from pre-edge state
            t_end   = m_en && (m_count <= 32'd1);
            n_en    = m_en; n_ie = m_ie; n_mode = m_mode;
            n_count = m_count; n_exp = m_expired; n_load = m_load;
            if (t_end) begin
                n_exp = 1'b1;
                if (m_mode) n_count = m_load;
                else begin n_count = 32'd0; n_en = 1'b0; end
            end else if (m_en) begin
                n_count = m_count - 32'd1;
            end
            if (t_clr && !t_end) n_exp = 1'b0;
            if (t_ctrl) begin
                n_ie = t_ed[1]; n_mode = t_ed[2]; n_en = t_ed[0];
                if (t_ed[0]) n_count = m_load;
            end
            if (t_loadw) begin
                for (i = 0; i < 4; i = i + 1)
                    if (t_es[i]) n_load[8*i +: 8] = t_ed[8*i +: 8];
            end

            // read capture uses pre-edge values
            if (t_ara) begin
                t_ra = eff(araddr);
                if (!mapped(t_ra)) begin
                    t_rv = 32'd0; m_rresp = SLVERR;
                end else begin
                    m_rresp = OKAY;
                    case (t_ra[3:2])
                        2'd0:    t_rv = {29'd0, m_mode, m_ie, m_en};
                        2'd1:    t_rv = m_load;
                        2'd2:    t_rv = m_count;
                        default: t_rv = {31'd0, m_expired};
                    endcase
                end
                m_rdata  = t_rv;
                m_rvalid = 1'b1;
            end else if (m_rvalid && rready) begin
                m_rvalid = 1'b0;
            end

            // write channel
            if (t_fire) begin
                m_awheld = 1'b0; m_wheld = 1'b0; m_bvalid = 1'b1;
                m_bresp  = t_ok ? OKAY : SLVERR;
            end else begin
                if (t_awa) begin m_awheld = 1'b1; m_awaddr = eff(awaddr); end
                if (t_wa)  begin m_wheld = 1'b1; m_wdata = wdata; m_wstrb = wstrb; end
                if (m_bvalid && bready) m_bvalid = 1'b0;
            end

            m_en = n_en; m_ie = n_ie; m_mode = n_mode;
            m_count = n_count; m_expired = n_exp; m_load = n_load;
        end
    end

    // ---------------------------------------------------------------
    // Per-cycle checker (mid-cycle, after all edge updates)
    // ---------------------------------------------------------------
    always @(negedge aclk) begin : checker_blk
        reg ok;
        if (chk_en) begin
            ok = 1'b1;
            if (awready_o !== (!m_awheld && !m_bvalid)) begin
                ok = 1'b0; $error("edge %0d AW%0d: awready %b, expected %b", edge_cnt, sel ? 8 : 4, awready_o, !m_awheld && !m_bvalid);
            end
            if (wready_o !== (!m_wheld && !m_bvalid)) begin
                ok = 1'b0; $error("edge %0d AW%0d: wready %b, expected %b", edge_cnt, sel ? 8 : 4, wready_o, !m_wheld && !m_bvalid);
            end
            if (arready_o !== !m_rvalid) begin
                ok = 1'b0; $error("edge %0d AW%0d: arready %b, expected %b", edge_cnt, sel ? 8 : 4, arready_o, !m_rvalid);
            end
            if (bvalid_o !== m_bvalid) begin
                ok = 1'b0; $error("edge %0d AW%0d: bvalid %b, expected %b", edge_cnt, sel ? 8 : 4, bvalid_o, m_bvalid);
            end
            if (m_bvalid && (bresp_o !== m_bresp)) begin
                ok = 1'b0; $error("edge %0d AW%0d: bresp %b, expected %b", edge_cnt, sel ? 8 : 4, bresp_o, m_bresp);
            end
            if (rvalid_o !== m_rvalid) begin
                ok = 1'b0; $error("edge %0d AW%0d: rvalid %b, expected %b", edge_cnt, sel ? 8 : 4, rvalid_o, m_rvalid);
            end
            if (m_rvalid && (rresp_o !== m_rresp)) begin
                ok = 1'b0; $error("edge %0d AW%0d: rresp %b, expected %b", edge_cnt, sel ? 8 : 4, rresp_o, m_rresp);
            end
            if (m_rvalid && (rdata_o !== m_rdata)) begin
                ok = 1'b0; $error("edge %0d AW%0d: rdata %h, expected %h", edge_cnt, sel ? 8 : 4, rdata_o, m_rdata);
            end
            if (irq_o !== (m_expired && m_ie)) begin
                ok = 1'b0; $error("edge %0d AW%0d: irq %b, expected %b", edge_cnt, sel ? 8 : 4, irq_o, m_expired && m_ie);
            end
            if (ok) passed = passed + 1;
            else    failed = failed + 1;
        end
    end

    // ---------------------------------------------------------------
    // Check tasks
    // ---------------------------------------------------------------
    task chk;
        input          c;
        input [8*64-1:0] msg;
        begin
            if (c === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("CHECK FAILED (ADDR_WIDTH %0d, edge %0d): %0s", sel ? 8 : 4, edge_cnt, msg);
            end
        end
    endtask

    task chk32;
        input [31:0]     got;
        input [31:0]     exp;
        input [8*64-1:0] msg;
        begin
            if (got === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("CHECK FAILED (ADDR_WIDTH %0d, edge %0d): %0s: got %h expected %h", sel ? 8 : 4, edge_cnt, msg, got, exp);
            end
        end
    endtask

    // ---------------------------------------------------------------
    // Stimulus tasks. Inputs change 1 time unit after a rising edge.
    // ---------------------------------------------------------------
    task step;
        begin
            @(posedge aclk);
            #1;
        end
    endtask

    task wait_edge;
        input integer t;
        begin
            while (edge_cnt < t) step;
        end
    endtask

    task do_reset;
        input integer n;
        begin
            aresetn = 1'b0;
            awvalid = 1'b0; wvalid = 1'b0; bready = 1'b0; arvalid = 1'b0; rready = 1'b0;
            repeat (n) step;
            aresetn = 1'b1;
        end
    endtask

    task wait_irq;
        integer n;
        begin
            n = 0;
            irq_at = -1;
            while ((n < 300) && (irq_at < 0)) begin
                @(negedge aclk);
                if (irq_o === 1'b1) irq_at = edge_cnt;
                n = n + 1;
            end
            @(posedge aclk);
            #1;
        end
    endtask

    task xfer;
        input        dw;
        input [7:0]  wa;
        input [31:0] wd;
        input [3:0]  ws;
        input [31:0] awd;
        input [31:0] wdd;
        input [31:0] bd;
        input        dr;
        input [7:0]  ra;
        input [31:0] ard;
        input [31:0] rdd;
        integer cyc, bcnt, rcnt;
        reg awp, wp, bp, arp, rp, awh, wh, bh, arh, rh;
        begin
            awp = dw; wp = dw; bp = dw; arp = dr; rp = dr;
            cyc = 0; bcnt = 0; rcnt = 0;
            awaddr = wa; wdata = wd; wstrb = ws; araddr = ra;
            while ((awp || wp || bp || arp || rp) && (cyc < 300)) begin
                awvalid = awp && (cyc >= awd);
                wvalid  = wp && (cyc >= wdd);
                bready  = dw && (bcnt >= bd);
                arvalid = arp && (cyc >= ard);
                rready  = dr && (rcnt >= rdd);
                @(negedge aclk);
                awh = awvalid && awready_o;
                wh  = wvalid && wready_o;
                bh  = bvalid_o && bready;
                arh = arvalid && arready_o;
                rh  = rvalid_o && rready;
                if (dw && bvalid_o) bcnt = bcnt + 1;
                if (dr && rvalid_o) rcnt = rcnt + 1;
                if ((awh || wh) && !((awp && !awh) || (wp && !wh))) wr_cmpl_edge = edge_cnt + 1;
                if (bh) last_bresp = bresp_o;
                if (arh) rd_acc_edge = edge_cnt + 1;
                if (rh) begin last_rdata = rdata_o; last_rresp = rresp_o; end
                @(posedge aclk);
                #1;
                if (awh) awp = 1'b0;
                if (wh)  wp  = 1'b0;
                if (bh)  bp  = 1'b0;
                if (arh) arp = 1'b0;
                if (rh)  rp  = 1'b0;
                cyc = cyc + 1;
            end
            if (cyc >= 300) begin
                failed = failed + 1;
                $error("transfer timed out (ADDR_WIDTH %0d, edge %0d)", sel ? 8 : 4, edge_cnt);
            end
            awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0; bready = 1'b0; rready = 1'b0;
        end
    endtask

    task wr;
        input [7:0]  a;
        input [31:0] d;
        input [3:0]  s;
        begin
            xfer(1'b1, a, d, s, 0, 0, 0, 1'b0, 8'h00, 0, 0);
        end
    endtask

    task rd;
        input [7:0] a;
        begin
            xfer(1'b0, 8'h00, 32'd0, 4'd0, 0, 0, 0, 1'b1, a, 0, 0);
        end
    endtask

    task wr_chk;
        input [7:0]      a;
        input [31:0]     d;
        input [3:0]      s;
        input [1:0]      er;
        input [8*64-1:0] msg;
        begin
            wr(a, d, s);
            chk32({30'd0, last_bresp}, {30'd0, er}, msg);
        end
    endtask

    task rd_chk;
        input [7:0]      a;
        input [31:0]     ed;
        input [1:0]      er;
        input [8*64-1:0] msg;
        begin
            rd(a);
            chk32(last_rdata, ed, msg);
            chk32({30'd0, last_rresp}, {30'd0, er}, msg);
        end
    endtask

    // ---------------------------------------------------------------
    // Test suite
    // ---------------------------------------------------------------
    task run_suite;
        input s;
        integer E, A, S, C, R, k, e1, e2;
        begin
            chk_en = 1'b0;
            sel = s;
            do_reset(3);
            chk_en = 1'b1;

            // Reset values
            chk(awready_o === 1'b1 && wready_o === 1'b1 && arready_o === 1'b1, "readies high after reset");
            chk(bvalid_o === 1'b0 && rvalid_o === 1'b0 && irq_o === 1'b0, "bvalid rvalid irq low after reset");
            rd_chk(A_CTRL, 32'd0, OKAY, "CTRL reset value");
            rd_chk(A_LOAD, 32'd0, OKAY, "LOAD reset value");
            rd_chk(A_COUNT, 32'd0, OKAY, "COUNT reset value");
            rd_chk(A_STATUS, 32'd0, OKAY, "STATUS reset value");

            // LOAD and strobes
            wr_chk(A_LOAD, 32'hFFFF_FFFF, 4'hF, OKAY, "LOAD full write resp");
            rd_chk(A_LOAD, 32'hFFFF_FFFF, OKAY, "LOAD readback");
            wr_chk(A_LOAD, 32'h1234_5678, 4'b0101, OKAY, "LOAD partial write resp");
            rd_chk(A_LOAD, 32'hFF34_FF78, OKAY, "LOAD partial strobes");
            wr_chk(A_LOAD, 32'h0000_0000, 4'b0000, OKAY, "LOAD empty strobe resp");
            rd_chk(A_LOAD, 32'hFF34_FF78, OKAY, "LOAD empty strobe changes nothing");
            wr_chk(A_LOAD, 32'hAB00_0000, 4'b1000, OKAY, "LOAD top byte resp");
            rd_chk(A_LOAD, 32'hAB34_FF78, OKAY, "LOAD top byte only");

            // CTRL strobes
            wr_chk(A_CTRL, 32'hFFFF_FFF6, 4'b1110, OKAY, "CTRL without wstrb0 resp");
            rd_chk(A_CTRL, 32'd0, OKAY, "CTRL unchanged without wstrb0");
            wr_chk(A_CTRL, 32'hFFFF_FFF6, 4'b0001, OKAY, "CTRL write resp");
            rd_chk(A_CTRL, 32'h0000_0006, OKAY, "CTRL IE MODE set, upper bits read 0");
            wr_chk(A_CTRL, 32'd0, 4'b0001, OKAY, "CTRL clear resp");
            rd_chk(A_CTRL, 32'd0, OKAY, "CTRL cleared");

            // Error responses and decode
            wr_chk(A_COUNT, 32'h1234_5678, 4'hF, SLVERR, "COUNT write SLVERR");
            rd_chk(A_COUNT, 32'd0, OKAY, "COUNT unchanged by write");
            wr_chk(8'h02, 32'hFFFF_FFFF, 4'hF, SLVERR, "misaligned write 0x2 SLVERR");
            wr_chk(8'h05, 32'h0000_0000, 4'hF, SLVERR, "misaligned write 0x5 SLVERR");
            rd_chk(A_CTRL, 32'd0, OKAY, "misaligned write leaves CTRL");
            rd_chk(A_LOAD, 32'hAB34_FF78, OKAY, "misaligned write leaves LOAD");
            rd_chk(8'h01, 32'd0, SLVERR, "misaligned read 0x1");
            rd_chk(8'h07, 32'd0, SLVERR, "misaligned read 0x7");
            rd_chk(8'h0E, 32'd0, SLVERR, "misaligned read 0xE");
            if (s) begin
                rd_chk(8'h10, 32'd0, SLVERR, "read 0x10 unmapped");
                rd_chk(8'h14, 32'd0, SLVERR, "read 0x14 unmapped");
                rd_chk(8'hFC, 32'd0, SLVERR, "read 0xFC unmapped");
                wr_chk(8'h14, 32'h5555_5555, 4'hF, SLVERR, "write 0x14 SLVERR");
                wr_chk(8'h40, 32'h0000_0007, 4'hF, SLVERR, "write 0x40 SLVERR");
                rd_chk(A_LOAD, 32'hAB34_FF78, OKAY, "0x14 does not alias LOAD");
                rd_chk(A_CTRL, 32'd0, OKAY, "0x40 does not alias CTRL");
            end

            // One-shot N=5 with interrupt
            wr(A_LOAD, 32'd5, 4'hF);
            wr(A_CTRL, 32'h3, 4'b0001);
            E = wr_cmpl_edge;
            wait_irq;
            chk32(irq_at - E, 32'd5, "one-shot N=5 ends on edge E+5");
            rd_chk(A_CTRL, 32'h2, OKAY, "one-shot end clears EN");
            rd_chk(A_COUNT, 32'd0, OKAY, "one-shot end COUNT 0");
            rd_chk(A_STATUS, 32'd1, OKAY, "EXPIRED set");
            rd_chk(A_STATUS, 32'd1, OKAY, "STATUS read does not clear");
            chk(irq_o === 1'b1, "irq high while EXPIRED and IE");
            wr_chk(A_STATUS, 32'd0, 4'hF, OKAY, "STATUS write 0 resp");
            chk(irq_o === 1'b1, "STATUS write of 0 keeps EXPIRED");
            wr_chk(A_STATUS, 32'd1, 4'b1110, OKAY, "STATUS no wstrb0 resp");
            chk(irq_o === 1'b1, "STATUS clear needs wstrb0");
            wr_chk(A_CTRL, 32'd0, 4'b0001, OKAY, "CTRL IE=0 resp");
            chk(irq_o === 1'b0, "IE=0 masks irq");
            rd_chk(A_STATUS, 32'd1, OKAY, "EXPIRED raw while masked");
            wr_chk(A_CTRL, 32'h2, 4'b0001, OKAY, "CTRL IE=1 resp");
            chk(irq_o === 1'b1, "IE=1 with EXPIRED raises irq");
            wr_chk(A_STATUS, 32'd1, 4'b0001, OKAY, "STATUS clear resp");
            chk(irq_o === 1'b0, "STATUS clear lowers irq");
            rd_chk(A_STATUS, 32'd0, OKAY, "EXPIRED cleared");

            // COUNT read during count, N=20
            wr(A_LOAD, 32'd20, 4'hF);
            wr(A_CTRL, 32'h1, 4'b0001);
            E = wr_cmpl_edge;
            rd(A_COUNT);
            A = rd_acc_edge;
            chk32(last_rdata, 20 - (A - 1 - E), "COUNT reads N-k");
            step; step; step;
            rd(A_COUNT);
            A = rd_acc_edge;
            chk32(last_rdata, 20 - (A - 1 - E), "COUNT reads N-k later");
            xfer(1'b0, 8'h00, 32'd0, 4'd0, 0, 0, 0, 1'b1, A_COUNT, 0, 5);
            A = rd_acc_edge;
            chk32(last_rdata, 20 - (A - 1 - E), "rdata held at capture under R stall");
            // Stop
            wr(A_CTRL, 32'd0, 4'b0001);
            S = wr_cmpl_edge;
            rd(A_COUNT);
            chk32(last_rdata, 20 - (S - E), "stop edge decrements then holds");
            step; step; step; step; step;
            rd_chk(A_COUNT, 20 - (S - E), OKAY, "COUNT holds while stopped");
            wr(A_CTRL, 32'd0, 4'b0001);
            rd_chk(A_COUNT, 20 - (S - E), OKAY, "EN 0 again leaves COUNT");
            rd_chk(A_CTRL, 32'd0, OKAY, "stopped CTRL");
            rd_chk(A_STATUS, 32'd0, OKAY, "no end before stop");

            // Restart with new MODE
            wr(A_LOAD, 32'd50, 4'hF);
            wr(A_CTRL, 32'h1, 4'b0001);
            step; step;
            wr(A_CTRL, 32'h5, 4'b0001);
            R = wr_cmpl_edge;
            rd(A_COUNT);
            A = rd_acc_edge;
            chk32(last_rdata, 50 - (A - 1 - R), "restart reloads COUNT");
            rd_chk(A_CTRL, 32'h5, OKAY, "restart takes new MODE");
            wr(A_CTRL, 32'd0, 4'b0001);

            // LOAD write during a one-shot count
            wr(A_LOAD, 32'd10, 4'hF);
            wr(A_CTRL, 32'h3, 4'b0001);
            E = wr_cmpl_edge;
            wr(A_LOAD, 32'd100, 4'hF);
            wait_irq;
            chk32(irq_at - E, 32'd10, "LOAD write mid-count keeps running count");
            rd_chk(A_LOAD, 32'd100, OKAY, "LOAD updated");
            wr(A_STATUS, 32'd1, 4'b0001);

            // LOAD 0 one-shot
            wr(A_LOAD, 32'd0, 4'hF);
            wr(A_CTRL, 32'h3, 4'b0001);
            E = wr_cmpl_edge;
            wait_irq;
            chk32(irq_at - E, 32'd1, "LOAD 0 one-shot ends on E+1");
            rd_chk(A_COUNT, 32'd0, OKAY, "LOAD 0 COUNT 0");
            rd_chk(A_CTRL, 32'h2, OKAY, "LOAD 0 one-shot clears EN");
            wr(A_STATUS, 32'd1, 4'b0001);

            // Periodic N=4
            wr(A_LOAD, 32'd4, 4'hF);
            wr(A_CTRL, 32'h7, 4'b0001);
            E = wr_cmpl_edge;
            wait_irq;
            chk32(irq_at - E, 32'd4, "periodic first end on E+N");
            for (k = 0; k < 3; k = k + 1) begin
                rd(A_COUNT);
                A = rd_acc_edge;
                chk32(last_rdata, 4 - ((A - 1 - E) % 4), "periodic COUNT value");
            end
            rd_chk(A_CTRL, 32'h7, OKAY, "periodic keeps EN");
            wr(A_STATUS, 32'd1, 4'b0001);
            C = wr_cmpl_edge;
            wait_irq;
            if (((C - E) % 4) == 0)
                chk32(irq_at, C + 1, "STATUS clear on end edge leaves irq");
            else
                chk32(irq_at, E + ((C - E) / 4 + 1) * 4, "periodic next end after clear");
            wr(A_CTRL, 32'h2, 4'b0001);
            S = wr_cmpl_edge;
            rd_chk(A_COUNT, 4 - ((S - E) % 4), OKAY, "periodic stop COUNT");
            rd_chk(A_CTRL, 32'h2, OKAY, "periodic stopped");
            wr(A_STATUS, 32'd1, 4'b0001);

            // Periodic LOAD 0: ends every edge, end beats clear
            wr(A_LOAD, 32'd0, 4'hF);
            wr(A_CTRL, 32'h7, 4'b0001);
            step; step;
            chk(irq_o === 1'b1, "periodic LOAD 0 ends every edge");
            wr(A_STATUS, 32'd1, 4'b0001);
            chk(irq_o === 1'b1, "end beats STATUS clear");
            rd_chk(A_STATUS, 32'd1, OKAY, "EXPIRED stays set");
            rd_chk(A_COUNT, 32'd0, OKAY, "periodic LOAD 0 COUNT 0");
            rd_chk(A_CTRL, 32'h7, OKAY, "periodic LOAD 0 EN stays");
            wr(A_CTRL, 32'd0, 4'b0001);
            wr(A_STATUS, 32'd1, 4'b0001);
            rd_chk(A_STATUS, 32'd0, OKAY, "cleared after stop");

            // CTRL EN=1 on a one-shot end edge
            wr(A_LOAD, 32'd6, 4'hF);
            wr(A_CTRL, 32'h1, 4'b0001);
            E = wr_cmpl_edge;
            wait_edge(E + 5);
            wr(A_CTRL, 32'h1, 4'b0001);
            chk32(wr_cmpl_edge, E + 6, "restart write lands on end edge");
            R = wr_cmpl_edge;
            rd_chk(A_STATUS, 32'd1, OKAY, "EXPIRED set when CTRL wins");
            rd(A_COUNT);
            A = rd_acc_edge;
            chk32(last_rdata, 6 - (A - 1 - R), "CTRL EN=1 on end edge restarts");
            wr(A_CTRL, 32'd0, 4'b0001);
            wr(A_STATUS, 32'd1, 4'b0001);

            // CTRL EN=0 on a one-shot end edge
            wr(A_LOAD, 32'd6, 4'hF);
            wr(A_CTRL, 32'h1, 4'b0001);
            E = wr_cmpl_edge;
            wait_edge(E + 5);
            wr(A_CTRL, 32'd0, 4'b0001);
            chk32(wr_cmpl_edge, E + 6, "stop write lands on one-shot end edge");
            rd_chk(A_COUNT, 32'd0, OKAY, "stop on one-shot end gives COUNT 0");
            rd_chk(A_CTRL, 32'd0, OKAY, "stop on one-shot end EN 0");
            rd_chk(A_STATUS, 32'd1, OKAY, "EXPIRED set on stop at end edge");
            wr(A_STATUS, 32'd1, 4'b0001);

            // CTRL EN=0 on a periodic end edge
            wr(A_LOAD, 32'd6, 4'hF);
            wr(A_CTRL, 32'h5, 4'b0001);
            E = wr_cmpl_edge;
            wait_edge(E + 5);
            wr(A_CTRL, 32'd0, 4'b0001);
            chk32(wr_cmpl_edge, E + 6, "stop write lands on periodic end edge");
            rd_chk(A_COUNT, 32'd6, OKAY, "stop on periodic end reloads LOAD");
            rd_chk(A_CTRL, 32'd0, OKAY, "stop on periodic end EN 0");
            rd_chk(A_STATUS, 32'd1, OKAY, "EXPIRED set on periodic stop edge");
            wr(A_STATUS, 32'd1, 4'b0001);

            // STATUS clear on a one-shot end edge
            wr(A_LOAD, 32'd6, 4'hF);
            wr(A_CTRL, 32'h1, 4'b0001);
            E = wr_cmpl_edge;
            wait_edge(E + 5);
            wr(A_STATUS, 32'd1, 4'b0001);
            chk32(wr_cmpl_edge, E + 6, "clear write lands on end edge");
            rd_chk(A_STATUS, 32'd1, OKAY, "end beats clear (one-shot)");
            wr(A_STATUS, 32'd1, 4'b0001);
            rd_chk(A_STATUS, 32'd0, OKAY, "clear after end works");

            // 32-bit decrement
            wr(A_LOAD, 32'hFFFF_FFFF, 4'hF);
            wr(A_CTRL, 32'h1, 4'b0001);
            E = wr_cmpl_edge;
            rd(A_COUNT);
            A = rd_acc_edge;
            chk32(last_rdata, 32'hFFFF_FFFF - (A - 1 - E), "32-bit count from all ones");
            wr(A_LOAD, 32'h0000_0100, 4'hF);
            wr(A_CTRL, 32'h1, 4'b0001);
            E = wr_cmpl_edge;
            rd(A_COUNT);
            A = rd_acc_edge;
            chk32(last_rdata, 32'h0000_0100 - (A - 1 - E), "decrement borrows across byte");
            wr(A_CTRL, 32'd0, 4'b0001);

            // AW/W ordering
            xfer(1'b1, A_LOAD, 32'h1111_1111, 4'hF, 0, 3, 0, 1'b0, 8'h00, 0, 0);
            chk32({30'd0, last_bresp}, {30'd0, OKAY}, "AW before W resp");
            rd_chk(A_LOAD, 32'h1111_1111, OKAY, "AW before W data");
            xfer(1'b1, A_LOAD, 32'h2222_2222, 4'hF, 3, 0, 0, 1'b0, 8'h00, 0, 0);
            chk32({30'd0, last_bresp}, {30'd0, OKAY}, "W before AW resp");
            rd_chk(A_LOAD, 32'h2222_2222, OKAY, "W before AW data");
            xfer(1'b1, A_COUNT, 32'h0, 4'hF, 0, 2, 0, 1'b0, 8'h00, 0, 0);
            chk32({30'd0, last_bresp}, {30'd0, SLVERR}, "held AW to COUNT SLVERR");

            // B back-pressure, and a read during the B stall
            xfer(1'b1, A_LOAD, 32'h3333_3333, 4'hF, 0, 0, 5, 1'b0, 8'h00, 0, 0);
            chk32({30'd0, last_bresp}, {30'd0, OKAY}, "B stall resp");
            xfer(1'b1, A_LOAD, 32'h4444_4444, 4'hF, 0, 0, 6, 1'b1, A_LOAD, 2, 0);
            chk32(rd_acc_edge - wr_cmpl_edge, 32'd2, "read not blocked by B stall");
            chk32(last_rdata, 32'h4444_4444, "read during B stall sees write");

            // Read and write of the same register on one edge
            xfer(1'b1, A_LOAD, 32'h5555_5555, 4'hF, 0, 0, 0, 1'b1, A_LOAD, 0, 0);
            chk32(rd_acc_edge, wr_cmpl_edge, "read and write on same edge");
            chk32(last_rdata, 32'h4444_4444, "same-edge read returns pre-edge value");
            rd_chk(A_LOAD, 32'h5555_5555, OKAY, "write took effect");

            // Throughput
            wr(A_LOAD, 32'd1, 4'hF);
            e1 = wr_cmpl_edge;
            wr(A_LOAD, 32'd2, 4'hF);
            e2 = wr_cmpl_edge;
            chk32(e2 - e1, 32'd2, "back-to-back writes every 2 edges");
            rd(A_LOAD);
            e1 = rd_acc_edge;
            rd(A_LOAD);
            e2 = rd_acc_edge;
            chk32(e2 - e1, 32'd2, "back-to-back reads every 2 edges");

            // Reset during traffic
            wr(A_LOAD, 32'd100, 4'hF);
            wr(A_CTRL, 32'h7, 4'b0001);
            awaddr = A_LOAD; wdata = 32'h9; wstrb = 4'hF; awvalid = 1'b1; wvalid = 1'b1; bready = 1'b0;
            araddr = A_COUNT; arvalid = 1'b1; rready = 1'b0;
            step;
            awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
            step; step;
            chk(bvalid_o === 1'b1 && rvalid_o === 1'b1, "responses pending before reset");
            aresetn = 1'b0;
            step;
            aresetn = 1'b1;
            chk(awready_o === 1'b1 && wready_o === 1'b1 && arready_o === 1'b1, "readies after mid-traffic reset");
            chk(bvalid_o === 1'b0 && rvalid_o === 1'b0 && irq_o === 1'b0, "valids irq after mid-traffic reset");
            rd_chk(A_CTRL, 32'd0, OKAY, "reset stops count");
            rd_chk(A_COUNT, 32'd0, OKAY, "reset COUNT");
            rd_chk(A_LOAD, 32'd0, OKAY, "reset LOAD");
            rd_chk(A_STATUS, 32'd0, OKAY, "reset STATUS");
            step; step;
        end
    endtask

    // ---------------------------------------------------------------
    // Main
    // ---------------------------------------------------------------
    initial begin
        passed = 0; failed = 0; edge_cnt = 0; chk_en = 1'b0;
        aclk = 1'b0; aresetn = 1'b0; sel = 1'b0;
